(v_topic_id, 'pertinent', '/ˈpɜːtɪnənt/', '(adj) thấu đáo, thích đáng, liên quan', 'The study revealed a pertinent aspect of modern development.', 'Test 4', 3, 88, NOW() + interval '6688 seconds'),
